import { useEffect, useState } from "react";
import axios from "axios";

function MisClasesAlumno({ user }) {
  const [clases, setClases] = useState([]);
  const [error, setError] = useState("");

  const token = localStorage.getItem("token");

  // Endpoint: /api/usuarios/:id/clases
  const fetchClases = async () => {
    if (!user || !user.id) return;
    try {
      const res = await axios.get(
        `http://localhost:3000/api/usuarios/${user.id}/clases`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      setClases(res.data);
    } catch {
      setError("Error al cargar tus clases.");
    }
  };

  useEffect(() => {
    fetchClases();
    // eslint-disable-next-line
  }, [user]);

  // Entrar a la clase (redirige a la ruta de clase, ajústalo según tu routing)
  const handleEntrarClase = (claseId) => {
    window.location.href = `/clase/${claseId}`;
  };

  return (
    <div className="p-4">
      <h2 className="text-2xl font-bold mb-4">📝 Todas Mis Clases</h2>
      {error && <p className="text-red-600">{error}</p>}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mt-6">
        {clases.length === 0 && (
          <div className="col-span-full text-center text-gray-500">
            No estás inscrito en ninguna clase.
          </div>
        )}
        {clases.map((clase) => (
          <div
            key={clase.id}
            className="bg-white p-4 rounded shadow border border-gray-200"
          >
            <h3 className="text-xl font-semibold">{clase.titulo}</h3>
            <p className="text-gray-600 mb-1">{clase.descripcion}</p>
            <div className="text-sm mb-2">
              <span className="font-bold">Fecha:</span> {clase.fecha} <br />
              <span className="font-bold">Hora:</span> {clase.hora}
            </div>
            <button
              onClick={() => handleEntrarClase(clase.id)}
              className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1 rounded text-xs"
            >
              Entrar a clase
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default MisClasesAlumno;
